import assert from 'node:assert/strict';
import { test } from 'node:test';

import { format, summarize } from '../src/commands/modes.mjs';

test('modes lists toolbar globals with their defaults and the chromatic modes', () => {
	const result = summarize({
		globalTypes: {
			theme: { toolbar: { items: [{ value: 'dark', title: 'Dark' }, 'light'] } },
			locale: { description: 'Language. Picks the strings.', toolbar: { items: ['en', 'pt'] } },
		},
		initialGlobals: { theme: 'dark', locale: 'en', outline: false },
		parameters: {
			chromatic: { modes: { light: { theme: 'light', viewport: { width: 1280 } } } },
		},
	});
	assert.deepEqual(
		result.globals.map((g) => [g.name, g.values, g.initial]),
		[
			['theme', ['dark', 'light'], 'dark'],
			['locale', ['en', 'pt'], 'en'],
		],
	);
	assert.deepEqual(result.modes, [
		{ name: 'light', globals: { theme: 'light' }, viewport: { width: 1280 } },
	]);
	const text = format({ ...result, clock: false, settleHook: false });
	assert.match(text, /theme\s+dark\* light\s+--theme/);
	assert.match(text, /locale\s+en\* pt\s+--globals\s+Language\.$/m);
	assert.match(text, /light\s+theme:light 1280$/m);
	assert.match(text, /nothing reads \?storyClock/);
});

test('a theme set only by initialGlobals still shows, and no globals says so', () => {
	const { globals } = summarize({ initialGlobals: { theme: 'light' } });
	assert.deepEqual(
		globals.map((g) => [g.name, g.values, g.initial]),
		[['theme', [], 'light']],
	);
	assert.match(
		format({ ...summarize({}), clock: true, settleHook: true }),
		/globals: none declared/,
	);
});

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';

import { changedStoryFiles } from '../src/changed.mjs';

const put = (file, content = '') => {
	mkdirSync(path.dirname(file), { recursive: true });
	writeFileSync(file, content);
};

const git = (cwd, ...args) =>
	spawnSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...args], { cwd });

test('changed-since walks sibling packages, root lockfiles and extra globs', async () => {
	const root = mkdtempSync(path.join(import.meta.dirname, '.tmp-'));
	const project = path.join(root, 'apps/web');
	const stats = path.join(project, 'preview-stats.json');
	try {
		put(path.join(root, 'yarn.lock'));
		put(path.join(root, 'packages/ui/button.ts'));
		put(path.join(project, '.storybook/preview.js'));
		put(path.join(project, 'src/page.ts'));
		put(path.join(project, 'src/theme.css'));
		put(path.join(project, 'src/page.stories.tsx'));
		put(
			stats,
			JSON.stringify({
				modules: [
					{ name: './../../packages/ui/button.ts', reasons: [{ moduleName: './src/page.ts' }] },
					{ name: './src/page.ts', reasons: [{ moduleName: './src/page.stories.tsx' }] },
					{ name: './src/page.stories.tsx', reasons: [] },
				],
			}),
		);
		git(root, 'init', '-q');
		git(root, 'add', '.');
		git(root, 'commit', '-qm', 'base');
		// Reached through a symlink, the way `.agent` or a linked checkout is.
		symlinkSync(root, `${root}-link`);
		const cwd = path.join(`${root}-link`, 'apps/web');
		const reach = (globs) => changedStoryFiles({ ref: 'HEAD', stats, cwd, globs });

		put(path.join(root, 'packages/ui/button.ts'), 'changed');
		assert.deepEqual([...(await reach()).files], ['./src/page.stories.tsx']);

		put(path.join(project, 'src/theme.css'), 'changed');
		assert.equal((await reach()).files.size, 1);
		assert.equal((await reach(['src/*.css'])).reason, 'src/theme.css');

		put(path.join(root, 'yarn.lock'), 'changed');
		assert.equal((await reach()).reason, '../../yarn.lock');
	} finally {
		rmSync(`${root}-link`, { force: true });
		rmSync(root, { recursive: true, force: true });
	}
});

import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';

import { tag } from '../src/commands/tag.mjs';
import { matchPairs, readTags } from '../src/review.mjs';

const files = ['dark/a--one.png', 'light/a--one.png', 'dark/a--two.png', 'dark/b--one.png'];

test('a pattern names a file, every theme of a story id, or a glob of either', () => {
	assert.deepEqual(matchPairs(files, ['dark/a--two.png']).matched, ['dark/a--two.png']);
	assert.deepEqual(matchPairs(files, ['a--one']).matched, ['dark/a--one.png', 'light/a--one.png']);
	assert.deepEqual(matchPairs(files, ['*--one']).matched, [
		'dark/a--one.png',
		'light/a--one.png',
		'dark/b--one.png',
	]);
	assert.deepEqual(matchPairs(files, ['a--o', 'b--one']).unmatched, ['a--o']);
});

test('sbshot tag adds, notes, removes, and writes nothing for a typo', async () => {
	const workspace = mkdtempSync(path.join(import.meta.dirname, '.tmp-'));
	const dir = path.join(workspace, 'diffs/base--after');
	mkdirSync(dir, { recursive: true });
	writeFileSync(
		path.join(dir, 'diff.json'),
		JSON.stringify({ results: files.map((file) => ({ file, changed: 1 })) }),
	);
	const run = (...args) => tag(['--workspace', workspace, 'base--after', ...args]);
	try {
		assert.equal(
			await run('fixed', 'a--one', '--theme', 'dark', '--note', 'now under the drawer'),
			0,
		);
		assert.equal(await run('fixed', 'b--one'), 0);
		assert.deepEqual(readTags(dir).fixed, {
			note: 'now under the drawer',
			files: ['dark/a--one.png', 'dark/b--one.png'],
		});

		assert.equal(await run('fixed', 'a--two', 'nope'), 1);
		assert.equal(readTags(dir).fixed.files.length, 2);

		assert.equal(await run('fixed', '--remove', 'b--one'), 0);
		assert.deepEqual(readTags(dir).fixed.files, ['dark/a--one.png']);
		assert.equal(await run('fixed', '--remove'), 0);
		assert.deepEqual(readTags(dir), {});

		assert.equal(await run('dark,wide', 'dark/*', '--note', 'dark mode'), 0);
		assert.deepEqual(Object.keys(readTags(dir)), ['dark', 'wide']);
		assert.deepEqual(readTags(dir).wide, {
			note: 'dark mode',
			files: ['dark/a--one.png', 'dark/a--two.png', 'dark/b--one.png'],
		});
		assert.equal(await run('dark,bad name', 'a--one'), 1);
		assert.equal(await run('dark,wide', '--remove', 'dark/a--two.png'), 0);
		assert.equal(readTags(dir).dark.files.length, 2);
		assert.equal(readTags(dir).wide.files.length, 2);
		assert.equal(await run('dark,wide', '--remove'), 0);
		assert.deepEqual(readTags(dir), {});
	} finally {
		rmSync(workspace, { recursive: true, force: true });
	}
});

import assert from 'node:assert/strict';
import { crc32, deflateSync } from 'node:zlib';
import { test } from 'node:test';

import { decodePng, sameImage, sizeOf } from '../src/png.mjs';

const SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

const chunk = (type, data = Buffer.alloc(0)) => {
	const length = Buffer.alloc(4);
	length.writeUInt32BE(data.length);
	const body = Buffer.concat([Buffer.from(type, 'latin1'), data]);
	const crc = Buffer.alloc(4);
	crc.writeUInt32BE(crc32(body));
	return Buffer.concat([length, body, crc]);
};

const header = (width, height, colorType = 6) => {
	const data = Buffer.alloc(13);
	data.writeUInt32BE(width, 0);
	data.writeUInt32BE(height, 4);
	data[8] = 8;
	data[9] = colorType;
	return chunk('IHDR', data);
};

/** An 8-bit PNG of `rows`, each a filter byte of 0 and its samples. */
const png = (width, height, rows, { colorType = 6, extra = [] } = {}) =>
	Buffer.concat([
		SIGNATURE,
		header(width, height, colorType),
		...extra,
		chunk('IDAT', deflateSync(Buffer.concat(rows.map((row) => Buffer.from([0, ...row]))))),
		chunk('IEND'),
	]);

test('a plain RGBA PNG decodes', () => {
	const image = decodePng(png(2, 1, [[255, 0, 0, 255, 0, 0, 255, 128]]));
	assert.deepEqual([...image.data], [255, 0, 0, 255, 0, 0, 255, 128]);
});

test('a damaged or oversized PNG is left to ImageMagick instead of throwing', () => {
	const good = png(2, 1, [[1, 2, 3, 4, 5, 6, 7, 8]]);
	// Cut inside the IDAT chunk.
	assert.equal(decodePng(good.subarray(0, good.length - 20)), null);
	// A palette image with no palette.
	assert.equal(decodePng(png(1, 1, [[0]], { colorType: 3 })), null);
	// Pixel data that is not zlib.
	const garbage = Buffer.concat([
		SIGNATURE,
		header(1, 1),
		chunk('IDAT', Buffer.from('nope')),
		chunk('IEND'),
	]);
	assert.equal(decodePng(garbage), null);
	// Fewer rows than the header says.
	assert.equal(decodePng(png(1, 2, [[1, 2, 3, 4]])), null);
	// A header that asks for more memory than any shot needs.
	assert.equal(decodePng(png(65535, 65535, [[0, 0, 0, 0]])), null);
});

test('a PNG cut inside its header has no size and is never the same image', () => {
	const cut = png(2, 1, [[1, 2, 3, 4, 5, 6, 7, 8]]).subarray(0, 20);
	assert.equal(sizeOf(cut), null);
	assert.equal(sameImage(cut, cut), false);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';

import { diffPair, maxDeltaFor } from '../src/pixels.mjs';

const image = (width, height, fill = [255, 255, 255, 255]) => {
	const data = Buffer.alloc(width * height * 4);
	for (let pos = 0; pos < data.length; pos += 4) {
		data.set(fill, pos);
	}
	return { width, height, data };
};

const paint = (img, x, y, rgba) => img.data.set(rgba, (y * img.width + x) * 4);

const options = {
	mode: 'green',
	maxDelta: maxDeltaFor(0.063),
	includeAA: false,
	highlight: [0, 224, 90],
};

test('identical images have no change', () => {
	assert.equal(diffPair(image(20, 20), image(20, 20), options).changed, 0);
});

test('a block that changes colour is counted and boxed', () => {
	const base = image(20, 20);
	const after = image(20, 20);
	for (let y = 5; y < 8; y += 1) {
		for (let x = 10; x < 14; x += 1) {
			paint(after, x, y, [0, 0, 0, 255]);
		}
	}
	const diff = diffPair(base, after, options);
	// The block's own corners read as antialiasing, as pixelmatch reads them.
	assert.ok(diff.changed >= 8 && diff.changed <= 12);
	assert.ok(diff.box.x >= 10 && diff.box.x + diff.box.width <= 14);
	assert.ok(diff.box.y >= 5 && diff.box.y + diff.box.height <= 8);
	assert.deepEqual([...diff.data.subarray((6 * 20 + 11) * 4, (6 * 20 + 11) * 4 + 3)], [0, 224, 90]);
});

test('a small shift in colour stays under the threshold', () => {
	const after = image(10, 10);
	paint(after, 5, 5, [250, 250, 250, 255]);
	assert.equal(diffPair(image(10, 10), after, options).changed, 0);
});

test('rows only one image has count as changed, and the box covers them', () => {
	const diff = diffPair(image(10, 10), image(10, 14), options);
	assert.equal(diff.changed, 40);
	assert.deepEqual(diff.box, { x: 0, y: 10, width: 10, height: 4 });
});

/** Pixels that differ from every neighbour, the same on every run. */
const noise = (width, height) => {
	const img = image(width, height);
	let seed = 7;
	for (let pos = 0; pos < img.data.length; pos += 4) {
		for (let channel = 0; channel < 3; channel += 1) {
			seed = (seed * 1103515245 + 12345) % 2 ** 31;
			img.data[pos + channel] = seed >> 23;
		}
	}
	return img;
};

/** White above row 60, a grey line on it, black below: an edge in the antialiasing sense. */
const edge = (width, height) => {
	const img = image(width, height);
	for (let y = 60; y < height; y += 1) {
		for (let x = 0; x < width; x += 1) {
			paint(img, x, y, y === 60 ? [128, 128, 128, 255] : [0, 0, 0, 255]);
		}
	}
	return img;
};

test('a wider baseline does not hide changes in the part both shots share', () => {
	const after = noise(100, 100);
	const same = diffPair(edge(100, 100), after, options).changed;
	assert.equal(diffPair(edge(200, 100), after, options).changed, same + 100 * 100);
});

test('shots that grew and shrank count each extra pixel once', () => {
	const diff = diffPair(image(100, 10), image(10, 100), options);
	assert.equal(diff.changed, 900);
});

import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, readlinkSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { test } from 'node:test';

import { jobState } from '../src/commands/status.mjs';
import { adoptResults, listJobs, resolveJob, validName } from '../src/workspace.mjs';

const put = (file, content = '') => {
	mkdirSync(path.dirname(file), { recursive: true });
	writeFileSync(file, content);
};

test('init links older runs and diffs and reports what it cannot read', async () => {
	const dir = mkdtempSync(path.join(import.meta.dirname, '.tmp-'));
	try {
		put(path.join(dir, 'tokens-before/s00/shots.json'), '{"shots":[]}');
		put(path.join(dir, 'tokens-before/s00/dark/a.png'));
		put(path.join(dir, 'old/diff/diff.json'), '{}');
		put(path.join(dir, 'tokens-diff/s00/dark/a.png'));
		put(path.join(dir, 'sb/iframe.html'));
		put(path.join(dir, 'sb/assets/logo.png'));

		const first = await adoptResults(dir);
		assert.deepEqual(first.linked.map(({ link }) => path.relative(dir, link)).sort(), [
			'diffs/old-diff',
			'runs/tokens-before-s00',
		]);
		assert.equal(readlinkSync(path.join(dir, 'runs/tokens-before-s00')), '../tokens-before/s00');
		assert.deepEqual(first.unreadable, [path.join(dir, 'tokens-diff/s00')]);
		assert.deepEqual(
			listJobs(dir)
				.map((job) => job.kind)
				.sort(),
			['capture', 'diff'],
		);

		const second = await adoptResults(dir);
		assert.equal(second.linked.length, 0);
		assert.equal(second.known.length, 2);
	} finally {
		rmSync(dir, { recursive: true, force: true });
	}
});

test('init links a source folder into another workspace', async () => {
	const dir = mkdtempSync(path.join(import.meta.dirname, '.tmp-'));
	try {
		put(path.join(dir, '.story-shots/before/shots.json'), '{"shots":[]}');
		const workspace = path.join(dir, '.sbshot');
		const { linked } = await adoptResults(path.join(dir, '.story-shots'), workspace);
		assert.deepEqual(
			linked.map(({ link }) => path.relative(workspace, link)),
			['runs/before'],
		);
		assert.equal(readlinkSync(path.join(workspace, 'runs/before')), '../../.story-shots/before');
		assert.equal((await adoptResults(path.join(dir, '.story-shots'), workspace)).linked.length, 0);
	} finally {
		rmSync(dir, { recursive: true, force: true });
	}
