		const escaping = { ...plan, entries: [{ path: '../evil.txt', data: Buffer.from('x') }] };
		await assert.rejects(writeExport(escaping, out), /outside itself/);
		assert.ok(!existsSync(path.join(root, 'evil.txt')));
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
});

{
	"$schema": "./node_modules/oxlint/configuration_schema.json",
	"env": {
		"node": true,
		"browser": true
	},
	"ignorePatterns": [".primus/**"],
	"rules": {
		"no-unused-vars": ["error", { "ignoreRestSiblings": true }]
	}
}

import { captureView } from './capture.js';
import { diffView } from './diff.js';
import { home } from './home.js';
import { leaveView, lightbox } from './shared.js';

/** A segment of the hash, or null for one that is not valid percent-encoding. */
const decode = (part) => {
	try {
		return decodeURIComponent(part);
	} catch {
		return null;
	}
};

const route = () => {
	leaveView();
	lightbox.hidden = true;
	const hash = location.hash.replace(/^#/, '') || '/';
	const [pathPart, query = ''] = hash.split('?');
	const params = new URLSearchParams(query);
	const parts = pathPart.split('/').filter(Boolean).map(decode);
	if (parts[0] === 'job' && parts.length === 3 && parts[2] !== null) {
		return parts[1] === 'diff' ? diffView(parts[2], params) : captureView(parts[2], params);
	}
	return home();
};

window.addEventListener('hashchange', route);

document.addEventListener('keydown', (event) => {
	if (event.key === 'Escape') lightbox.hidden = true;
});

route();

/**
 * The diff page's current view drawn at the shots' own resolution: a PNG for
 * the still views, a GIF for blink. What is drawn follows the page's CSS
 * (`.side`, `.stack`, `.changebox`), not its size on screen.
 */
import { encodeGif } from './gif.js';

const GAP = 8;
const LABEL = 24;
const BLINK = 600;

const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

/** A shot without its caption band, or null when the pair has no such shot. */
const load = async (source) => {
	if (!source) return null;
	const image = new Image();
	image.src = source.src;
	await image.decode();
	return {
		image,
		top: source.top,
		width: image.naturalWidth,
		height: Math.max(image.naturalHeight - source.top, 1),
	};
};

const canvasOf = (width, height) => {
	const canvas = document.createElement('canvas');
	canvas.width = Math.round(width);
	canvas.height = Math.round(height);
	const context = canvas.getContext('2d');
	context.fillStyle = css('--bg');
	context.fillRect(0, 0, canvas.width, canvas.height);
	return { canvas, context };
};

/** A shot scaled to `width`, or the placeholder text where it is missing. */
const drawShot = (context, shot, x, y, width, height, missing) => {
	if (shot) {
		const scaled = (shot.height * width) / shot.width;
		context.drawImage(shot.image, 0, shot.top, shot.width, shot.height, x, y, width, scaled);
		return;
	}
	context.fillStyle = css('--panel');
	context.fillRect(x, y, width, height);
	context.fillStyle = css('--muted');
	context.font = '14px system-ui, sans-serif';
	context.textAlign = 'center';
	context.fillText(missing, x + width / 2, y + Math.min(height / 2, 150));
	context.textAlign = 'left';
};

const drawLabel = (context, text, x, y, width) => {
	context.fillStyle = css('--panel');
	context.fillRect(x, y, width, LABEL);
	context.fillStyle = css('--muted');
	context.font = '12px system-ui, sans-serif';
	context.textBaseline = 'middle';
	context.fillText(text, x + 6, y + LABEL / 2);
	context.textBaseline = 'alphabetic';
};

/** The change box over a tile of `width` x `height` showing the pair. */
const drawBox = (context, pair, x, y, width, height) => {
	if (!pair.box || !pair.width || !pair.height) return;
	const scale = width / pair.width;
	const box = {
		x: x + pair.box.x * scale,
		y: y + pair.box.y * scale,
		width: Math.max(pair.box.width * scale, width * 0.003),
		height: Math.max(pair.box.height * scale, height * 0.003),
	};
	context.save();
	context.beginPath();
	context.rect(x, y, width, height);
	context.rect(box.x, box.y, box.width, box.height);
	context.fillStyle = 'rgba(0, 0, 0, 0.18)';
	context.fill('evenodd');
	context.setLineDash([6, 4]);
	context.lineWidth = 2;
	context.strokeStyle = '#ff2d55';
	context.strokeRect(box.x, box.y, box.width, box.height);
	context.restore();
};

const png = (canvas) =>
	new Promise((resolve, reject) =>
		canvas.toBlob(
			(blob) => (blob ? resolve(blob) : reject(new Error('the view is too large to draw'))),
			'image/png',
		),
	);

/**
 * `sources` holds `{ src, top }` for `base`, `after` and `diff`, null for a
 * missing one; `view` is the page's mode, box toggle, swipe split and onion
 * opacity. Resolves to `{ blob, type }`.
 */
export const snapshot = async (pair, sources, view) => {
	const [base, after, diff] = await Promise.all([
		load(sources.base),
		load(sources.after),
		load(sources.diff),
	]);
	const box = (context, x, y, width, height) =>
		view.box && drawBox(context, pair, x, y, width, height);

	if (view.mode === 'diff') {
		const shot = diff ?? after ?? base;
		const width = shot?.width ?? pair.width ?? 800;
		const height = shot ? (shot.height * width) / shot.width : 300;
		const { canvas, context } = canvasOf(width, height);
		drawShot(context, diff, 0, 0, width, height, 'no diff image: the pair is identical');
		box(context, 0, 0, width, height);
		return { blob: await png(canvas), type: 'png' };
	}

	if (view.mode === 'side' || view.mode === 'side3') {
		const tiles = [
			['baseline', base, 'missing in baseline'],
			['after', after, 'missing in after'],
			...(view.mode === 'side3' ? [['diff', diff, 'no diff image: the pair is identical']] : []),
		];
		const column = Math.max(...tiles.map(([, shot]) => shot?.width ?? 0)) || pair.width || 800;
		const tall = Math.max(
			300,
			...tiles.map(([, shot]) => (shot ? (shot.height * column) / shot.width : 0)),
		);
		const { canvas, context } = canvasOf(
			tiles.length * column + (tiles.length - 1) * GAP,
			LABEL + tall,
		);
		tiles.forEach(([label, shot, missing], index) => {
			const x = index * (column + GAP);
			const height = shot ? (shot.height * column) / shot.width : 300;
			drawLabel(context, label, x, 0, column);
			drawShot(context, shot, x, LABEL, column, height, missing);
			box(context, x, LABEL, column, height);
		});
		return { blob: await png(canvas), type: 'png' };
	}

	// The stacked views: the after shot sets the size, the baseline is drawn
	// over it at the same width and cut to it.
	const width = after?.width ?? base?.width ?? pair.width ?? 800;
	const height = after ? after.height : base ? (base.height * width) / base.width : 300;
	const stack = (context, y, { baseline = true, alpha = 1, split = 100 } = {}) => {
		drawShot(context, after, 0, y, width, height, 'missing in after');
		if (baseline && base) {
			context.save();
			context.beginPath();
			context.rect(0, y, (width * split) / 100, height);
			context.clip();
			context.globalAlpha = alpha;
			drawShot(context, base, 0, y, width, height);
			context.restore();
		}
		box(context, 0, y, width, height);
	};

	if (view.mode === 'blink') {
		const frames = [true, false].map((baseline) => {
			const { context } = canvasOf(width, LABEL + height);
			drawLabel(context, baseline ? 'baseline' : 'after', 0, 0, width);
			stack(context, LABEL, { baseline });
			return context.getImageData(0, 0, context.canvas.width, context.canvas.height).data;
		});
		return {
			blob: encodeGif(frames, Math.round(width), Math.round(LABEL + height), BLINK),
			type: 'gif',
		};
	}

	const { canvas, context } = canvasOf(width, height);
	if (view.mode === 'swipe') {
		stack(context, 0, { split: view.split });
		context.fillStyle = css('--accent');
		context.fillRect((width * view.split) / 100 - 1, 0, 2, height);
	} else {
		stack(context, 0, { alpha: view.opacity / 100 });
	}
	return { blob: await png(canvas), type: 'png' };
};

/**
 * An animated GIF from RGBA frames of one size, looping forever. The frames
 * share one palette, so a pixel that does not change between frames keeps its
 * colour: a per-frame palette would make identical regions flicker.
 */

const key = (r, g, b) => (r << 16) | (g << 8) | b;
const bin = (r, g, b) => ((r >> 3) << 10) | ((g >> 3) << 5) | (b >> 3);

/** Up to 256 colours for the frames, and the index of every pixel. */
const quantize = (frames) => {
	const exact = new Map();
	for (const data of frames) {
		for (let i = 0; i < data.length && exact.size <= 256; i += 4) {
			const color = key(data[i], data[i + 1], data[i + 2]);
			if (!exact.has(color)) exact.set(color, exact.size);
		}
	}
	if (exact.size <= 256) {
		const palette = [...exact.keys()].map((color) => [
			color >> 16,
			(color >> 8) & 255,
			color & 255,
		]);
		const indices = frames.map((data) => {
			const out = new Uint8Array(data.length / 4);
			for (let i = 0; i < out.length; i += 1) {
				out[i] = exact.get(key(data[i * 4], data[i * 4 + 1], data[i * 4 + 2]));
			}
			return out;
		});
		return { palette, indices };
	}

	// Median cut over 15-bit bins, each bin standing for the mean of its pixels.
	// A box is split where its colours spread the most, so a small accent
	// colour keeps its own entry beside a large background.
	const count = new Uint32Array(32768);
	const sum = new Float64Array(32768 * 3);
	for (const data of frames) {
		for (let i = 0; i < data.length; i += 4) {
			const b = bin(data[i], data[i + 1], data[i + 2]);
			count[b] += 1;
			sum[b * 3] += data[i];
			sum[b * 3 + 1] += data[i + 1];
			sum[b * 3 + 2] += data[i + 2];
		}
	}
	const bins = [];
	for (let b = 0; b < 32768; b += 1) {
		if (count[b])
			bins.push({
				n: count[b],
				c: [sum[b * 3] / count[b], sum[b * 3 + 1] / count[b], sum[b * 3 + 2] / count[b]],
			});
	}
	const spread = (box) => {
		let best = { range: -1, channel: 0 };
		for (let channel = 0; channel < 3; channel += 1) {
			let low = 255;
			let high = 0;
			for (const item of box) {
				low = Math.min(low, item.c[channel]);
				high = Math.max(high, item.c[channel]);
			}
			if (high - low > best.range) best = { range: high - low, channel };
		}
		return best;
	};
	const boxes = [bins];
	while (boxes.length < 256) {
		let pick = -1;
		let widest = { range: 0 };
		boxes.forEach((box, index) => {
			if (box.length < 2) return;
			const found = spread(box);
			if (found.range > widest.range) {
				widest = found;
				pick = index;
			}
		});
		if (pick < 0) break;
		const box = boxes[pick].sort((a, b) => a.c[widest.channel] - b.c[widest.channel]);
		const total = box.reduce((acc, item) => acc + item.n, 0);
		let seen = 0;
		let cut = 1;
		while (cut < box.length - 1 && seen + box[cut - 1].n < total / 2) {
			seen += box[cut - 1].n;
			cut += 1;
		}
		boxes.splice(pick, 1, box.slice(0, cut), box.slice(cut));
	}
	const palette = boxes.map((box) => {
		const total = box.reduce((acc, item) => acc + item.n, 0);
		return [0, 1, 2].map((channel) =>
			Math.round(box.reduce((acc, item) => acc + item.c[channel] * item.n, 0) / total),
		);
	});
	const lookup = new Uint8Array(32768);
	for (let b = 0; b < 32768; b += 1) {
		if (!count[b]) continue;
		const [r, g, bl] = [
			sum[b * 3] / count[b],
			sum[b * 3 + 1] / count[b],
			sum[b * 3 + 2] / count[b],
		];
		let nearest = 0;
		let distance = Infinity;
		palette.forEach(([pr, pg, pb], index) => {
			const d = (pr - r) ** 2 + (pg - g) ** 2 + (pb - bl) ** 2;
			if (d < distance) {
				distance = d;
				nearest = index;
			}
		});
		lookup[b] = nearest;
	}
	const indices = frames.map((data) => {
		const out = new Uint8Array(data.length / 4);
		for (let i = 0; i < out.length; i += 1) {
			out[i] = lookup[bin(data[i * 4], data[i * 4 + 1], data[i * 4 + 2])];
		}
		return out;
	});
	return { palette, indices };
};

class Bytes {
	buffer = new Uint8Array(1 << 16);
	length = 0;
	push(...values) {
		for (const value of values) {
			if (this.length === this.buffer.length) {
				const grown = new Uint8Array(this.buffer.length * 2);
				grown.set(this.buffer);
				this.buffer = grown;
			}
			this.buffer[this.length++] = value;
		}
	}
	word(value) {
		this.push(value & 255, value >> 8);
	}
	text(value) {
		this.push(...[...value].map((char) => char.charCodeAt(0)));
	}
	bytes() {
		return this.buffer.subarray(0, this.length);
	}
}

/** The LZW stream of one frame, cut into the sub-blocks GIF wants. */
const lzw = (indices, minSize, out) => {
	const clear = 1 << minSize;
	const end = clear + 1;
	const data = new Bytes();
	let size = minSize + 1;
	let next = end + 1;
	let table = new Map();
	let bits = 0;
	let pending = 0;
	const emit = (code) => {
		pending |= code << bits;
		bits += size;
		while (bits >= 8) {
			data.push(pending & 255);
			pending >>= 8;
			bits -= 8;
		}
	};
	emit(clear);
	let prefix = indices[0];
	for (let i = 1; i < indices.length; i += 1) {
		const pixel = indices[i];
		const entry = (prefix << 8) | pixel;
		const code = table.get(entry);
		if (code !== undefined) {
			prefix = code;
			continue;
		}
		emit(prefix);
		if (next === 4096) {
			emit(clear);
			table = new Map();
			size = minSize + 1;
			next = end + 1;
		} else {
			if (next >= 1 << size) size += 1;
			table.set(entry, next++);
		}
		prefix = pixel;
	}
	emit(prefix);
	emit(end);
	if (bits > 0) data.push(pending & 255);

	out.push(minSize);
	const stream = data.bytes();
	for (let start = 0; start < stream.length; start += 255) {
		const block = stream.subarray(start, start + 255);
		out.push(block.length, ...block);
	}
	out.push(0);
};

/** `frames` are RGBA pixel arrays of `width` x `height`, each shown for `delay` ms. */
export const encodeGif = (frames, width, height, delay) => {
	const { palette, indices } = quantize(frames);
	const depth = Math.max(1, Math.ceil(Math.log2(palette.length)));
	const out = new Bytes();
	out.text('GIF89a');
	out.word(width);
	out.word(height);
	out.push(0xf0 | (depth - 1), 0, 0);
	for (let index = 0; index < 1 << depth; index += 1) {
		out.push(...(palette[index] ?? [0, 0, 0]));
	}
	// Loop forever.
	out.push(0x21, 0xff, 11);
	out.text('NETSCAPE2.0');
	out.push(3, 1, 0, 0, 0);
	for (const frame of indices) {
		out.push(0x21, 0xf9, 4, 0x04);
		out.word(Math.round(delay / 10));
		out.push(0, 0);
		out.push(0x2c);
		out.word(0);
		out.word(0);
		out.word(width);
		out.word(height);
		out.push(0);
		lzw(frame, Math.max(2, depth), out);
	}
	out.push(0x3b);
	return new Blob([out.bytes()], { type: 'image/gif' });
};
